// Generated by VibeStack. A complete React app for this backend, with no build step and no CDN:
// React, ReactDOM, htm and the CSS are in static/vendor/, so it also works offline.
// What it shows comes from static/config.json (the backend design) and static/ui.json (the look).
const React = window.React;
const { useCallback, useEffect, useMemo, useState } = React;
const { createRoot } = window.ReactDOM;
const html = window.htm.bind(React.createElement);

const [CFG, UI] = await Promise.all([
  fetch("static/config.json").then((r) => r.json()),
  fetch("static/ui.json").then((r) => r.json()).catch(() => ({})),
]);
const ACCENT = UI.accent || "indigo";
const APP_NAME = UI.app_name || CFG.project;
const TOKEN_KEY = `token:${CFG.project}`;
const REFRESH_KEY = `refresh:${CFG.project}`;
const FEATURES = CFG.features || [];
const SIGNUP_ROLES = (CFG.roles || []).filter((r) => r.self_signup).map((r) => r.name);
document.title = APP_NAME;

// ---------------------------------------------------------------------------- talking to the API

const getToken = () => localStorage.getItem(TOKEN_KEY) || "";
const setToken = (t) => (t ? localStorage.setItem(TOKEN_KEY, t) : localStorage.removeItem(TOKEN_KEY));
const getRefresh = () => localStorage.getItem(REFRESH_KEY) || "";
const setRefresh = (t) => (t ? localStorage.setItem(REFRESH_KEY, t) : localStorage.removeItem(REFRESH_KEY));

// Access tokens are short-lived when refresh tokens are on: trade the refresh token for a new pair once.
async function renewLogin() {
  if (!getRefresh()) return false;
  const res = await fetch("auth/refresh", {
    method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ refresh_token: getRefresh() }),
  });
  if (!res.ok) return setRefresh(""), false;
  const data = await res.json();
  setToken(data.access_token);
  setRefresh(data.refresh_token);
  return true;
}

class ApiError extends Error {
  constructor(status, message, fields) {
    super(message);
    this.status = status;
    this.fields = fields || {};
  }
}

function explain(detail, fallback) {
  // FastAPI-style errors: a string, or a list of {loc, msg}.
  if (typeof detail === "string") return { message: detail, fields: {} };
  if (Array.isArray(detail)) {
    const fields = {};
    for (const d of detail) fields[(d.loc || []).slice(-1)[0]] = d.msg;
    return { message: detail.map((d) => `${(d.loc || []).slice(-1)[0]}: ${d.msg}`).join("; "), fields };
  }
  return { message: fallback, fields: {} };
}

async function api(method, path, body, retried) {
  const headers = { "Content-Type": "application/json" };
  if (getToken()) headers.Authorization = `Bearer ${getToken()}`;
  const res = await fetch(path, { method, headers, body: body === undefined ? undefined : JSON.stringify(body) });
  if (res.status === 401 && !retried && !path.startsWith("auth/") && (await renewLogin())) return api(method, path, body, true);
  const text = await res.text();
  let data = null;
  try {
    data = text ? JSON.parse(text) : null;
  } catch {
    data = text;
  }
  if (!res.ok) {
    const { message, fields } = explain(data && data.detail, res.statusText);
    throw new ApiError(res.status, message, fields);
  }
  return { data, total: Number(res.headers.get("X-Total-Count") || NaN) };
}

const entityByName = Object.fromEntries(CFG.entities.map((e) => [e.name, e]));
const labelOf = (e) => (UI.entities && UI.entities[e.name] && UI.entities[e.name].label) || `${e.name}s`;
const iconOf = (e) => (UI.entities && UI.entities[e.name] && UI.entities[e.name].icon) || "•";
const pretty = (name) => name.replace(/_id$/, "").replace(/_/g, " ");

function display(value, field) {
  if (value === null || value === undefined || value === "") return html`<span className="text-slate-300">—</span>`;
  if (field && field.type === "bool") return value ? "Yes" : "No";
  if (field && field.type === "json") return html`<code className="text-xs text-slate-500">${JSON.stringify(value).slice(0, 60)}</code>`;
  if (field && field.type === "datetime") return new Date(value).toLocaleString();
  if (field && field.choices && field.choices.length) return html`<${Badge} text=${value} />`;
  return String(value);
}

function rowLabel(row) {
  if (!row) return "";
  const text = Object.entries(row).find(([k, v]) => typeof v === "string" && !["created_at", "status"].includes(k));
  return text ? text[1] : `#${row.id}`;
}

// ---------------------------------------------------------------------------- small building blocks

function Badge({ text }) {
  const palette = ["bg-sky-100 text-sky-700", "bg-emerald-100 text-emerald-700", "bg-amber-100 text-amber-700",
    "bg-violet-100 text-violet-700", "bg-rose-100 text-rose-700", "bg-slate-100 text-slate-700"];
  const i = [...String(text)].reduce((a, c) => a + c.charCodeAt(0), 0) % palette.length;
  return html`<span className=${`inline-flex rounded-full px-2 py-0.5 text-xs font-medium ${palette[i]}`}>${text}</span>`;
}

function Button({ children, onClick, kind = "primary", type = "button", disabled, small }) {
  const size = small ? "px-2.5 py-1 text-xs" : "px-3.5 py-2 text-sm";
  const styles = {
    primary: `bg-${ACCENT}-600 text-white hover:bg-${ACCENT}-700 shadow-sm`,
    ghost: "text-slate-600 hover:bg-slate-100",
    outline: "border border-slate-200 bg-white text-slate-700 hover:bg-slate-50",
    danger: "text-rose-600 hover:bg-rose-50",
  };
  return html`<button type=${type} disabled=${disabled} onClick=${onClick}
    className=${`inline-flex items-center gap-1.5 rounded-lg font-medium transition disabled:opacity-50 ${size} ${styles[kind]}`}>${children}</button>`;
}

function Toasts({ toasts }) {
  return html`<div className="fixed bottom-4 right-4 z-50 space-y-2">
    ${toasts.map((t) => html`<div key=${t.id} className=${`max-w-sm rounded-lg px-4 py-3 text-sm shadow-lg ring-1 ${
      t.kind === "error" ? "bg-rose-50 text-rose-800 ring-rose-200" : "bg-white text-slate-800 ring-slate-200"}`}>${t.text}</div>`)}
  </div>`;
}

function useToasts() {
  const [toasts, setToasts] = useState([]);
  const push = useCallback((text, kind = "info") => {
    const id = Math.random();
    setToasts((t) => [...t, { id, text, kind }]);
    setTimeout(() => setToasts((t) => t.filter((x) => x.id !== id)), 4000);
  }, []);
  return [toasts, push];
}

// ---------------------------------------------------------------------------- login

function Auth({ onLogin }) {
  const [mode, setMode] = useState("login");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [role, setRole] = useState(SIGNUP_ROLES[0] || "");
  const [error, setError] = useState("");
  async function submit(ev) {
    ev.preventDefault();
    setError("");
    try {
      if (mode === "register") await api("POST", "auth/register", { email, password, ...(role ? { role } : {}) });
      const { data } = await api("POST", "auth/login", { email, password });
      setToken(data.access_token);
      setRefresh(data.refresh_token || "");
      onLogin((await api("GET", "auth/me")).data);
    } catch (e) {
      setError(e.message);
    }
  }
  const input = "mt-1 w-full rounded-lg border border-slate-200 px-3 py-2 outline-none focus:border-slate-400";
  return html`<div className="grid min-h-screen place-items-center bg-gradient-to-br from-slate-50 to-slate-100 p-4">
    <form onSubmit=${submit} className="w-full max-w-sm rounded-2xl bg-white p-7 shadow-xl ring-1 ring-slate-200">
      <div className=${`mb-1 grid h-10 w-10 place-items-center rounded-xl bg-${ACCENT}-600 text-lg font-bold text-white`}>${APP_NAME[0]}</div>
      <h1 className="mt-3 text-xl font-semibold">${mode === "login" ? `Sign in to ${APP_NAME}` : `Create your ${APP_NAME} account`}</h1>
      <p className="mb-5 text-sm text-slate-500">${UI.tagline || ""}</p>
      <label className="block text-sm text-slate-600">Email<input type="email" required value=${email} onInput=${(e) => setEmail(e.target.value)} className=${input} /></label>
      <label className="mt-3 block text-sm text-slate-600">Password<input type="password" minLength="8" required value=${password} onInput=${(e) => setPassword(e.target.value)} className=${input} /></label>
      ${mode === "register" && SIGNUP_ROLES.length > 1 && html`<label className="mt-3 block text-sm text-slate-600">I am a
        <select value=${role} onChange=${(e) => setRole(e.target.value)} className=${input}>
          ${SIGNUP_ROLES.map((r) => html`<option key=${r} value=${r}>${pretty(r)}</option>`)}
        </select></label>`}
      ${error && html`<p className="mt-3 text-sm text-rose-600">${error}</p>`}
      <button className=${`mt-5 w-full rounded-lg bg-${ACCENT}-600 py-2.5 font-medium text-white hover:bg-${ACCENT}-700`}>${mode === "login" ? "Sign in" : "Create account"}</button>
      <button type="button" onClick=${() => setMode(mode === "login" ? "register" : "login")} className="mt-3 w-full text-sm text-slate-500 hover:text-slate-700">
        ${mode === "login" ? "No account? Create one" : "Have an account? Sign in"}
      </button>
    </form>
  </div>`;
}

// ---------------------------------------------------------------------------- forms

function FieldInput({ field, value, onChange, options, error }) {
  const base = `mt-1 w-full rounded-lg border px-3 py-2 text-sm outline-none focus:border-slate-400 ${error ? "border-rose-300" : "border-slate-200"}`;
  const label = html`<span className="text-sm font-medium text-slate-700">${pretty(field.name)}${field.required ? html`<span className="text-rose-500"> *</span>` : ""}</span>`;
  let input;
  if (field.references) {
    input = html`<select className=${base} value=${value ?? ""} onChange=${(e) => onChange(e.target.value === "" ? null : Number(e.target.value))}>
      <option value="">Choose ${pretty(field.name)}…</option>
      ${(options || []).map((o) => html`<option key=${o.id} value=${o.id}>#${o.id} ${rowLabel(o)}</option>`)}
    </select>`;
  } else if (field.choices && field.choices.length) {
    input = html`<select className=${base} value=${value ?? ""} onChange=${(e) => onChange(e.target.value || null)}>
      <option value="">Choose…</option>${field.choices.map((c) => html`<option key=${c} value=${c}>${c}</option>`)}
    </select>`;
  } else if (field.type === "bool") {
    input = html`<label className="mt-2 flex items-center gap-2 text-sm text-slate-600">
      <input type="checkbox" checked=${!!value} onChange=${(e) => onChange(e.target.checked)} /> ${pretty(field.name)}</label>`;
  } else if (field.type === "text" || field.type === "json") {
    const text = field.type === "json" && typeof value !== "string" ? (value == null ? "" : JSON.stringify(value, null, 2)) : (value ?? "");
    input = html`<textarea rows=${field.type === "json" ? 6 : 4} className=${`${base} ${field.type === "json" ? "font-mono text-xs" : ""}`}
      value=${text} onInput=${(e) => onChange(e.target.value)} placeholder=${field.type === "json" ? '{ "key": "value" }' : ""} />`;
  } else {
    const types = { int: "number", float: "number", decimal: "number", date: "date", datetime: "datetime-local" };
    const shown = field.type === "datetime" && value ? String(value).slice(0, 16) : (value ?? "");
    input = html`<input type=${types[field.type] || "text"} step=${field.type === "int" ? "1" : "any"}
      min=${field.min ?? undefined} max=${field.max ?? undefined} className=${base} value=${shown}
      onInput=${(e) => onChange(e.target.value)} />`;
  }
  return html`<label className="block">${field.type === "bool" ? "" : label}${input}
    ${error && html`<span className="mt-1 block text-xs text-rose-600">${error}</span>`}</label>`;
}

function toPayload(entity, form) {
  const out = {};
  for (const f of entity.fields) {
    let v = form[f.name];
    if (v === undefined) continue;
    if (v === "" || v === null) {
      if (!f.required) out[f.name] = null;
      continue;
    }
    if (f.type === "int") v = parseInt(v, 10);
    else if (f.type === "float" || f.type === "decimal") v = parseFloat(v);
    else if (f.type === "datetime" && String(v).length === 16) v = `${v}:00`;
    else if (f.type === "json" && typeof v === "string") {
      try {
        v = JSON.parse(v);
      } catch {
        throw new ApiError(422, `${f.name}: not valid JSON`, { [f.name]: "not valid JSON" });
      }
    }
    out[f.name] = v;
  }
  return out;
}

function Drawer({ entity, row, options, onClose, onSaved, toast }) {
  const [form, setForm] = useState(row ? { ...row } : {});
  const [errors, setErrors] = useState({});
  const [busy, setBusy] = useState(false);
  async function save(ev) {
    ev.preventDefault();
    setBusy(true);
    setErrors({});
    try {
      const body = toPayload(entity, form);
      if (row) await api("PATCH", `${entity.table}/${row.id}`, body);
      else await api("POST", `${entity.table}/`, body);
      toast(`${entity.name} ${row ? "updated" : "created"}`);
      onSaved();
    } catch (e) {
      setErrors(e.fields || {});
      toast(e.message, "error");
    } finally {
      setBusy(false);
    }
  }
  return html`<div className="fixed inset-0 z-40 flex justify-end bg-slate-900/30 backdrop-blur-[1px]" onClick=${onClose}>
    <form onSubmit=${save} onClick=${(e) => e.stopPropagation()} className="flex h-full w-full max-w-md flex-col bg-white shadow-2xl">
      <div className="border-b border-slate-100 px-6 py-4">
        <h2 className="text-lg font-semibold">${row ? `Edit ${entity.name} #${row.id}` : `New ${entity.name}`}</h2>
      </div>
      <div className="flex-1 space-y-4 overflow-y-auto px-6 py-5">
        ${entity.fields.map((f) => html`<${FieldInput} key=${f.name} field=${f} value=${form[f.name]} error=${errors[f.name]}
          options=${options[f.references]} onChange=${(v) => setForm((s) => ({ ...s, [f.name]: v }))} />`)}
      </div>
      <div className="flex justify-end gap-2 border-t border-slate-100 px-6 py-4">
        <${Button} kind="ghost" onClick=${onClose}>Cancel</${Button}>
        <${Button} type="submit" disabled=${busy}>${busy ? "Saving…" : "Save"}</${Button}>
      </div>
    </form>
  </div>`;
}

// ---------------------------------------------------------------------------- pages

function useOptions(entity, me) {
  // Rows of every entity this one points at, for dropdowns and readable labels.
  const [options, setOptions] = useState({});
  useEffect(() => {
    (async () => {
      const out = {};
      for (const f of entity.fields.filter((f) => f.references)) {
        if (f.references === "User") out.User = me ? [me] : [];
        else if (entityByName[f.references]) {
          try {
            out[f.references] = (await api("GET", `${entityByName[f.references].table}/?limit=100`)).data;
          } catch {
            out[f.references] = [];
          }
        }
      }
      setOptions(out);
    })();
  }, [entity, me]);
  return options;
}

function EntityPage({ entity, me, toast }) {
  const [rows, setRows] = useState([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(0);
  const [q, setQ] = useState("");
  const [editing, setEditing] = useState(null);
  const [live, setLive] = useState(false);
  const options = useOptions(entity, me);
  const size = 20;
  const columns = entity.fields.filter((f) => f.type !== "text").slice(0, 6);

  const load = useCallback(async () => {
    const params = new URLSearchParams({ skip: page * size, limit: size });
    if (q && entity.search) params.set("q", q);
    try {
      const { data, total } = await api("GET", `${entity.table}/?${params}`);
      setRows(data);
      setTotal(Number.isNaN(total) ? data.length : total);
    } catch (e) {
      toast(e.message, "error");
    }
  }, [entity, page, q, toast]);

  useEffect(() => {
    load();
  }, [load]);

  useEffect(() => {
    if (!entity.realtime) return;
    const token = entity.access === "owner" ? `?token=${encodeURIComponent(getToken())}` : "";
    const source = new EventSource(`${entity.table}/stream${token}`);
    source.onopen = () => setLive(true);
    source.onerror = () => setLive(false);
    for (const kind of ["created", "updated", "deleted"]) source.addEventListener(kind, () => load());
    return () => source.close();
  }, [entity, load]);

  async function remove(row) {
    if (!confirm(`Delete ${entity.name} #${row.id}?`)) return;
    try {
      await api("DELETE", `${entity.table}/${row.id}`);
      toast(`${entity.name} deleted`);
      load();
    } catch (e) {
      toast(e.message, "error");
    }
  }

  async function move(row, field, to) {
    try {
      await api("PATCH", `${entity.table}/${row.id}`, { [field.name]: to });
      toast(`${pretty(field.name)} → ${to}`);
      load();
    } catch (e) {
      toast(e.message, "error");
    }
  }

  async function run(action, row) {
    const path = `${entity.table}${action.path.replace("{item_id}", row ? row.id : "")}`;
    try {
      const { data } = await api(action.method, path, action.method === "POST" ? {} : undefined);
      toast(`${action.name}: ${typeof data === "object" ? JSON.stringify(data).slice(0, 140) : data}`);
      load();
    } catch (e) {
      toast(`${action.name}: ${e.message}`, "error");
    }
  }

  const machines = entity.fields.filter((f) => f.transitions && Object.keys(f.transitions).length);
  const itemActions = entity.actions.filter((a) => a.path.startsWith("/{item_id}"));
  const listActions = entity.actions.filter((a) => !a.path.startsWith("/{item_id}"));

  return html`<div>
    <div className="mb-5 flex flex-wrap items-center gap-3">
      <div>
        <h1 className="flex items-center gap-2 text-2xl font-semibold"><span>${iconOf(entity)}</span>${labelOf(entity)}
          ${entity.realtime && html`<span className=${`flex items-center gap-1 rounded-full px-2 py-0.5 text-xs font-medium ${live ? "bg-emerald-50 text-emerald-700" : "bg-slate-100 text-slate-500"}`}>
            <span className=${`h-1.5 w-1.5 rounded-full ${live ? "animate-pulse bg-emerald-500" : "bg-slate-400"}`}></span>${live ? "Live" : "Offline"}</span>`}
        </h1>
        <p className="text-sm text-slate-500">${(UI.entities && UI.entities[entity.name] && UI.entities[entity.name].description) || `${total} record${total === 1 ? "" : "s"}`}</p>
      </div>
      <div className="ml-auto flex flex-wrap gap-2">
        ${listActions.map((a) => html`<${Button} key=${a.name} kind="outline" onClick=${() => run(a)}>⚙ ${pretty(a.name)}</${Button}>`)}
        <${Button} onClick=${() => setEditing({})}>+ New ${entity.name}</${Button}>
      </div>
    </div>
    ${entity.search && html`<input placeholder=${`Search ${pretty(entity.search)}…`} value=${q}
      onInput=${(e) => { setQ(e.target.value); setPage(0); }}
      className="mb-4 w-full max-w-sm rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm outline-none focus:border-slate-400" />`}
    <div className="overflow-hidden rounded-xl bg-white shadow-sm ring-1 ring-slate-200">
      <table className="w-full text-left text-sm">
        <thead className="bg-slate-50 text-xs uppercase tracking-wide text-slate-500">
          <tr><th className="px-4 py-3">#</th>${columns.map((f) => html`<th key=${f.name} className="px-4 py-3">${pretty(f.name)}</th>`)}<th></th></tr>
        </thead>
        <tbody>
          ${rows.length === 0 && html`<tr><td colSpan=${columns.length + 2} className="px-4 py-14 text-center text-slate-400">
            Nothing here yet. <button className=${`font-medium text-${ACCENT}-600`} onClick=${() => setEditing({})}>Create the first ${entity.name.toLowerCase()}</button>
          </td></tr>`}
          ${rows.map((row) => html`<tr key=${row.id} className="border-t border-slate-100 hover:bg-slate-50/60">
            <td className="px-4 py-3 font-mono text-xs text-slate-400">${row.id}</td>
            ${columns.map((f) => html`<td key=${f.name} className="max-w-[220px] truncate px-4 py-3">
              ${f.references ? html`<span className="text-slate-600">${rowLabel((options[f.references] || []).find((o) => o.id === row[f.name])) || display(row[f.name], f)}</span>` : display(row[f.name], f)}
            </td>`)}
            <td className="whitespace-nowrap px-4 py-2 text-right">
              ${machines.flatMap((f) => (f.transitions[row[f.name]] || []).map((to) => html`<${Button} key=${f.name + to} small kind="outline" onClick=${() => move(row, f, to)}>→ ${to}</${Button}>`))}
              ${itemActions.map((a) => html`<${Button} key=${a.name} small kind="outline" onClick=${() => run(a, row)}>${pretty(a.name)}</${Button}>`)}
              <${Button} small kind="ghost" onClick=${() => setEditing(row)}>Edit</${Button}>
              <${Button} small kind="danger" onClick=${() => remove(row)}>Delete</${Button}>
            </td>
          </tr>`)}
        </tbody>
      </table>
    </div>
    ${total > size && html`<div className="mt-3 flex items-center justify-end gap-2 text-sm text-slate-500">
      <${Button} small kind="outline" disabled=${page === 0} onClick=${() => setPage(page - 1)}>Previous</${Button}>
      <span>${page * size + 1}–${Math.min(total, (page + 1) * size)} of ${total}</span>
      <${Button} small kind="outline" disabled=${(page + 1) * size >= total} onClick=${() => setPage(page + 1)}>Next</${Button}>
    </div>`}
    ${editing && html`<${Drawer} entity=${entity} row=${editing.id ? editing : null} options=${options} toast=${toast}
      onClose=${() => setEditing(null)} onSaved=${() => { setEditing(null); load(); }} />`}
  </div>`;
}

function Dashboard({ toast }) {
  const [values, setValues] = useState({});
  const cards = (UI.dashboard && UI.dashboard.length ? UI.dashboard : CFG.entities.slice(0, 4).map((e) => ({ title: labelOf(e), entity: e.name })))
    .filter((c) => entityByName[c.entity]);
  useEffect(() => {
    (async () => {
      const out = {};
      for (const [i, card] of cards.entries()) {
        const e = entityByName[card.entity];
        try {
          if (card.group_by) {
            const { data } = await api("GET", `${e.table}/?limit=100`);
            const counts = {};
            for (const row of data) counts[row[card.group_by]] = (counts[row[card.group_by]] || 0) + 1;
            out[i] = counts;
          } else {
            const { data, total } = await api("GET", `${e.table}/?limit=1`);
            out[i] = Number.isNaN(total) ? data.length : total;
          }
        } catch (err) {
          out[i] = "–";
        }
      }
      setValues(out);
    })();
  }, []);
  return html`<div>
    <h1 className="text-2xl font-semibold">Welcome to ${APP_NAME}</h1>
    <p className="mb-6 text-sm text-slate-500">${UI.tagline || CFG.description || ""}</p>
    <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
      ${cards.map((card, i) => html`<a key=${i} href=${`#/${entityByName[card.entity].table}`}
        className="rounded-xl bg-white p-5 shadow-sm ring-1 ring-slate-200 transition hover:shadow-md">
        <div className="text-sm text-slate-500">${card.title}</div>
        ${card.group_by && typeof values[i] === "object"
          ? html`<div className="mt-3 flex flex-wrap gap-1.5">${Object.entries(values[i]).map(([k, n]) => html`<span key=${k} className="text-sm"><${Badge} text=${`${k}: ${n}`} /></span>`)}
              ${Object.keys(values[i]).length === 0 && html`<span className="text-sm text-slate-400">No data yet</span>`}</div>`
          : html`<div className="mt-2 text-3xl font-semibold tracking-tight">${values[i] ?? "…"}</div>`}
      </a>`)}
    </div>
    <div className="mt-8 grid gap-3 sm:grid-cols-2 xl:grid-cols-3">
      ${CFG.entities.map((e) => html`<a key=${e.name} href=${`#/${e.table}`} className="flex items-center gap-3 rounded-xl bg-white p-4 ring-1 ring-slate-200 hover:ring-slate-300">
        <span className="text-xl">${iconOf(e)}</span>
        <div><div className="font-medium">${labelOf(e)}</div><div className="text-xs text-slate-500">${e.fields.length} fields${e.actions.length ? ` · ${e.actions.length} actions` : ""}${e.realtime ? " · live" : ""}</div></div>
      </a>`)}
    </div>
  </div>`;
}

// ---------------------------------------------------------------------------- audit log (admins)

function AuditPage({ toast }) {
  const [rows, setRows] = useState([]);
  useEffect(() => {
    api("GET", "audit_logs/?limit=100").then((r) => setRows(r.data), (e) => toast(e.message, "error"));
  }, [toast]);
  return html`<div>
    <h1 className="text-2xl font-semibold">Audit log</h1>
    <p className="mb-5 text-sm text-slate-500">Every change, who made it and when. Entries cannot be edited or deleted.</p>
    <div className="overflow-x-auto rounded-xl border border-slate-200 bg-white">
      <table className="w-full text-left text-sm">
        <thead className="border-b border-slate-200 text-slate-500"><tr>
          ${["When", "User", "Action", "Record"].map((h) => html`<th key=${h} className="px-4 py-2 font-medium">${h}</th>`)}
        </tr></thead>
        <tbody>${rows.map((r) => html`<tr key=${r.id} className="border-b border-slate-100">
          <td className="px-4 py-2 text-slate-500">${new Date(r.created_at).toLocaleString()}</td>
          <td className="px-4 py-2">${r.actor_id ?? "—"}</td>
          <td className="px-4 py-2"><${Badge} text=${r.action} /></td>
          <td className="px-4 py-2">${r.entity}${r.row_id ? ` #${r.row_id}` : ""}</td>
        </tr>`)}</tbody>
      </table>
    </div>
  </div>`;
}

// ---------------------------------------------------------------------------- the app shell

function useRoute() {
  const [hash, setHash] = useState(location.hash);
  useEffect(() => {
    const on = () => setHash(location.hash);
    addEventListener("hashchange", on);
    return () => removeEventListener("hashchange", on);
  }, []);
  return hash.replace(/^#\/?/, "");
}

function App() {
  const [me, setMe] = useState(null);
  const [ready, setReady] = useState(!CFG.auth);
  const [toasts, toast] = useToasts();
  const route = useRoute();
  const entity = useMemo(() => CFG.entities.find((e) => e.table === route), [route]);

  useEffect(() => {
    if (!CFG.auth || !getToken()) return setReady(true);
    api("GET", "auth/me").then((r) => setMe(r.data), () => setToken("")).finally(() => setReady(true));
  }, []);

  if (!ready) return null;
  if (CFG.auth && !me) return html`<${Auth} onLogin=${setMe} />`;
  const showAudit = FEATURES.includes("audit_log") && me && me.is_admin;
  const signOut = () => {
    if (getRefresh()) api("POST", "auth/logout", { refresh_token: getRefresh() }).catch(() => {});
    setToken("");
    setRefresh("");
    setMe(null);
  };

  const nav = (href, active, icon, text) => html`<a href=${href} className=${`flex items-center gap-2.5 rounded-lg px-3 py-2 text-sm ${
    active ? `bg-${ACCENT}-50 font-medium text-${ACCENT}-700` : "text-slate-600 hover:bg-slate-100"}`}><span className="w-5 text-center">${icon}</span>${text}</a>`;

  return html`<div className="flex min-h-screen">
    <aside className="hidden w-60 shrink-0 flex-col border-r border-slate-200 bg-white p-4 md:flex">
      <div className="mb-6 flex items-center gap-2.5 px-2">
        <div className=${`grid h-8 w-8 place-items-center rounded-lg bg-${ACCENT}-600 font-bold text-white`}>${APP_NAME[0]}</div>
        <span className="truncate font-semibold">${APP_NAME}</span>
      </div>
      <nav className="space-y-1">
        ${nav("#/", !entity && route !== "audit", "⌂", "Dashboard")}
        ${CFG.entities.map((e) => html`<div key=${e.name}>${nav(`#/${e.table}`, entity === e, iconOf(e), labelOf(e))}</div>`)}
        ${showAudit && nav("#/audit", route === "audit", "🧾", "Audit log")}
      </nav>
      ${me && html`<div className="mt-auto border-t border-slate-100 pt-4 text-sm">
        <div className="truncate px-2 text-slate-600">${me.email}</div>
        ${(me.role || me.is_admin) && html`<div className="px-2 text-xs text-slate-400">${me.is_admin ? "admin" : pretty(me.role)}</div>`}
        <button className="mt-1 px-2 text-slate-400 hover:text-slate-700" onClick=${signOut}>Sign out</button>
      </div>`}
    </aside>
    <main className="min-w-0 flex-1">
      <div className="flex items-center gap-2 border-b border-slate-200 bg-white px-4 py-3 md:hidden">
        <select className="flex-1 rounded-lg border border-slate-200 px-2 py-1.5 text-sm" value=${route} onChange=${(e) => (location.hash = `#/${e.target.value}`)}>
          <option value="">Dashboard</option>${CFG.entities.map((e) => html`<option key=${e.name} value=${e.table}>${labelOf(e)}</option>`)}
          ${showAudit && html`<option value="audit">Audit log</option>`}
        </select>
      </div>
      <div className="mx-auto max-w-6xl px-5 py-8">
        ${entity ? html`<${EntityPage} key=${entity.name} entity=${entity} me=${me} toast=${toast} />`
          : route === "audit" && showAudit ? html`<${AuditPage} toast=${toast} />` : html`<${Dashboard} toast=${toast} />`}
      </div>
    </main>
    <${Toasts} toasts=${toasts} />
  </div>`;
}

createRoot(document.getElementById("root")).render(html`<${App} />`);
